{
  "schema_version": "13.0",
  "description": "Externalized prompt templates for LIC v13.0 - All agent prompts, generation templates, and critique templates",

  "cta_templates": {
    "CONNECTION_REQ": {
      "default": null,
      "_comment": "CONNECTION_REQ has no CTA per SPEC 3"
    },
    "INMAIL": {
      "C_LEVEL": "Would you be open to a brief conversation about how [TOPIC] might align with your strategic priorities?",
      "EXECUTIVE": "I'd welcome the chance to discuss how [TOPIC] could support your team's objectives.",
      "SENIOR_TA": {
        "direct": "Would you have 15 minutes to discuss [TECHNICAL_TOPIC]?",
        "deferential": "If this aligns with your team's direction, I'd appreciate any guidance you could share."
      },
      "RECRUITER": "Would you be open to a conversation about roles that might match your team's needs?"
    },
    "EMAIL": {
      "C_LEVEL": "I'd value the opportunity to explore how [TOPIC] aligns with your vision for [COMPANY].",
      "EXECUTIVE": "Would you be open to a brief call to discuss [TOPIC]?",
      "SENIOR_TA": {
        "direct": "Could we schedule 20 minutes to dive into [TECHNICAL_TOPIC]?",
        "deferential": "If this resonates with your team's roadmap, I'd be grateful for any insights you could offer."
      },
      "RECRUITER": "I'd welcome a conversation about potential opportunities that could benefit your team."
    },
    "FOLLOW_UP": {
      "default": "Following up on my previous message - would you have time for a brief conversation this week?"
    }
  },

  "archetype_generation_templates": {
    "C_LEVEL": {
      "system_instructions": "You are crafting an executive-level message that demonstrates thought leadership and strategic alignment.",
      "tone": "Strategic, confident, focused on business impact and organizational transformation.",
      "approach": "Lead with macro trends, demonstrate understanding of strategic challenges, position yourself as a peer with complementary expertise.",
      "avoid": "Tactical details, overt sales language, assumptions about their specific pain points.",
      "key_principles": [
        "Speak to business outcomes, not features",
        "Use industry context and market trends",
        "Demonstrate strategic thinking",
        "Position as a peer conversation, not a pitch",
        "Reference organizational transformation and competitive advantage"
      ]
    },
    "EXECUTIVE": {
      "system_instructions": "You are crafting a professional message that emphasizes collaboration and mutual value.",
      "tone": "Professional, collaborative, focused on team objectives and operational excellence.",
      "approach": "Reference their role and responsibilities, demonstrate understanding of their team's challenges, offer concrete value.",
      "avoid": "Overly formal language, generic value propositions, excessive deference.",
      "key_principles": [
        "Focus on team impact and operational outcomes",
        "Demonstrate understanding of their domain",
        "Offer specific, actionable value",
        "Balance professionalism with warmth",
        "Show respect for their time and priorities"
      ]
    },
    "SENIOR_TA": {
      "system_instructions": "You are crafting a technical message for a senior technical authority (architect, principal engineer, tech lead).",
      "tone": "Technical peer, respectful but confident, focused on architectural decisions and technical excellence.",
      "approach": "Reference specific technologies or patterns, demonstrate technical credibility, respect their authority on technical direction.",
      "avoid": "Marketing language, oversimplification of technical concepts, challenging their technical decisions.",
      "key_principles": [
        "Use appropriate technical terminology",
        "Reference specific technologies, frameworks, or patterns",
        "Demonstrate deep technical understanding",
        "Position as a technical peer, not a subordinate",
        "Show respect for their architectural decisions",
        "Focus on technical challenges and solutions"
      ]
    },
    "RECRUITER": {
      "system_instructions": "You are crafting a job-focused message that centers on role fit and candidate qualifications.",
      "tone": "Warm, professional, focused on alignment between candidate skills and role requirements.",
      "approach": "Lead with relevant experience, highlight specific skills that match job description, emphasize career growth potential.",
      "avoid": "Generic qualifications, vague interest statements, over-selling unrelated experience.",
      "key_principles": [
        "Lead with most relevant experience",
        "Connect specific skills to job requirements",
        "Show enthusiasm for the role and company",
        "Demonstrate understanding of the position",
        "Focus on mutual fit, not just interest",
        "Be concise and scannable"
      ]
    }
  },

  "generation_system_prompt": {
    "core_identity": "You are an expert at crafting personalized, high-signal professional outreach messages.",
    "core_principles": [
      "Every word must count - no filler, no generic statements",
      "Ground all claims in research evidence",
      "Write as a peer, not a supplicant",
      "Lead with value, not need",
      "Be specific and concrete, never vague",
      "Use active voice and confident phrasing"
    ],
    "forbidden_patterns": [
      "Placeholder text like [TOPIC], [COMPANY], etc.",
      "Weak phrases: 'I hope', 'I wanted to', 'just reaching out'",
      "Corporate clichés: 'spearheaded', 'leveraged', 'synergized'",
      "Generic statements that could apply to anyone",
      "Unsupported claims about sender capabilities"
    ],
    "required_patterns": [
      "Specific references to recipient's work, role, or recent activity",
      "Clear connection between sender experience and recipient needs",
      "Concrete value proposition",
      "Natural, conversational tone",
      "Perfect grammar and professional formatting"
    ]
  },

  "strategic_alignment_prompt_template": {
    "_comment": "v12.0 Strategic Alignment Generation - the main generation prompt template",
    "template": "You are an expert at crafting executive-level strategic outreach. Your persona is \"{persona}\".\n\nYour communication principles are:\n{principles}\n\n---\nMY CAPABILITIES (GROUND TRUTH):\n{sender_summary}\n\n---\nTHEIR PRIORITIES (GROUND TRUTH):\n{recipient_summary}\n\n---\nTHE MISSION:\nYou will draft a peer-to-peer message for the target defined in `mission_input_LIC.json`.\n\nCRITICAL REQUIREMENTS:\n- The message MUST align my specific capabilities with their stated strategic priorities.\n- The message MUST be between {word_count_min} and {word_count_max} words.\n- The message MUST NOT contain any of these forbidden phrases: {forbidden}\n- The message MUST be confident, direct, and assume a peer-to-peer relationship.\n- DO NOT use flattery. DO NOT use social hooks. Focus only on strategic, data-driven alignment.\n- Use specific metrics from MY CAPABILITIES when relevant.\n- Reference specific initiatives/priorities from THEIR PRIORITIES when possible.\n- NO placeholders like [TOPIC], [COMPANY], [NAME] - use actual names and specifics.\n\nROUTE CONTEXT:\n- Message type: {route}\n- Recipient archetype: {archetype}\n{adversarial_constraints}\n\nDraft the complete message. Output ONLY the message content, no preamble or explanation.",
    "variables": {
      "persona": "From sender_voice_profile.json",
      "principles": "From sender_voice_profile.json - formatted as bullet list",
      "sender_summary": "Top 5 capabilities from MASTER_RESUME + SENDER_KNOWLEDGE_BASE RAG results",
      "recipient_summary": "Top 5 priorities from STRATEGIC_BRIEF or high-value context RAG results",
      "word_count_min": "target - 30",
      "word_count_max": "target + 30",
      "forbidden": "From sender_voice_profile.json - comma-separated",
      "route": "From scaffold.route.value",
      "archetype": "From scaffold.archetype.value",
      "adversarial_constraints": "Optional adversarial findings prefixed with warning"
    }
  },

  "sender_voice_profile_template": {
    "_comment": "Template for rendering sender voice profile in prompts",
    "template": "SENDER PERSONA: {persona}\n\nSTYLE ATTRIBUTES:\n{style_attributes}\n\nPREFERRED LANGUAGE:\n{preferred_phrases}\n\nFORBIDDEN PHRASES (NEVER USE):\n{forbidden_phrases}\n\nCOMMUNICATION PRINCIPLES:\n- Write as a peer, not a supplicant\n- Lead with value, not need\n- Use active voice and confident phrasing\n- Avoid hedging language ('I think', 'maybe', 'perhaps')\n- Be direct but respectful\n- Focus on outcomes, not activities"
  },

  "rag_critique_prompt": {
    "_comment": "v11.10 RAG quality assessment prompt",
    "template": "You are a research quality assessor. Evaluate the following research findings for gaps and weaknesses.\n\nRESEARCH FINDINGS:\n{rag_summary}\n\nASSESSMENT CRITERIA:\n1. Recency: Are findings current (< 90 days preferred)?\n2. Specificity: Do we have recipient-specific insights vs. generic company info?\n3. Signal Quality: Are sources authoritative (LinkedIn, blog posts, press releases)?\n4. Coverage: Do we have insights across multiple dimensions (role, company, recent activity)?\n5. Actionability: Can these findings inform personalized outreach?\n\nIDENTIFY:\n- Critical gaps in research coverage\n- Weak or outdated sources\n- Missing recipient-specific insights\n- Areas requiring refinement\n\nOUTPUT FORMAT:\nCONFIDENCE_SCORE: [0.0-1.0]\nGAPS: [list specific gaps]\nREFINEMENT_TASKS: [specific searches to run]\nIS_SUFFICIENT: [true/false]\nREASONING: [brief explanation]",
    "variables": {
      "rag_summary": "Formatted summary of all RAGResults with source types and recency"
    }
  },

  "adversarial_critique_prompt": {
    "_comment": "v11.10 Adversarial research audit prompt",
    "template": "You are a skeptical research auditor. Your job is to find weaknesses in the research findings.\n\nRESEARCH CONTEXT:\n{research_summary}\n\nADVERSARIAL REVIEW:\nChallenge these findings by identifying:\n1. Unsupported claims or logical leaps\n2. Outdated information that may no longer be relevant\n3. Generic statements that could apply to any company/person\n4. Missing critical context for personalization\n5. Gaps where additional research would significantly improve message quality\n\nBe ruthless. If something seems weak, call it out. If a claim needs more support, flag it.\n\nOUTPUT FORMAT (one finding per line):\n- [Finding 1]\n- [Finding 2]\n- [Finding 3]",
    "variables": {
      "research_summary": "Formatted summary of research context including all insights and RAG results"
    }
  },

  "profile_analysis_prompt": {
    "_comment": "NEW v13.0: Externalized profile analysis logic",
    "template": "Analyze the following recipient profile and classify them into one of these archetypes:\n\nARCHETYPES:\n1. C_LEVEL: CEO, CTO, CFO, COO, Chief X Officer, President, Founder\n2. EXECUTIVE: VP, Vice President, Director, Head of, Lead\n3. SENIOR_TA: Principal Engineer, Staff Engineer, Senior Architect, Tech Lead, Engineering Manager\n4. RECRUITER: Recruiter, Talent Acquisition, Hiring Manager, HR\n\nRECIPIENT PROFILE:\nName: {name}\nTitle: {title}\nCompany: {company}\nLinkedIn URL: {linkedin_url}\n\nAnalyze the title and provide:\n1. ARCHETYPE: [one of the 4 archetypes]\n2. CONFIDENCE: [0.0-1.0]\n3. REASONING: [brief explanation]\n4. KEY_INDICATORS: [list of signals from the title]\n5. NEEDS_MANUAL_OVERRIDE: [true if confidence < 0.75]\n\nOutput as JSON.",
    "variables": {
      "name": "From mission.recipient_profile['name']",
      "title": "From mission.recipient_profile['title']",
      "company": "From mission.recipient_profile['company']",
      "linkedin_url": "From mission.recipient_profile['linkedin_url']"
    }
  },

  "routing_decision_prompt": {
    "_comment": "NEW v13.0: Externalized routing logic",
    "template": "Determine the optimal message route based on the following context:\n\nRECIPIENT STATUS:\n- Connection Status: {connection_status}\n- Prior Message Count: {prior_message_count}\n- Archetype: {archetype}\n\nROUTE OPTIONS:\n1. CONNECTION_REQ: For unconnected recipients (40-60 words, no CTA)\n2. INMAIL: For unconnected or 1st-time contact (180-250 words, subject required)\n3. EMAIL: For connected recipients or external email (200-350 words, subject required)\n4. FOLLOW_UP: For recipients with prior messages (150-220 words, references previous message)\n\nROUTING RULES:\n- If connection_status == 'not_connected' AND prior_message_count == 0 → CONNECTION_REQ\n- If connection_status == 'not_connected' AND prior_message_count > 0 → INMAIL or FOLLOW_UP\n- If connection_status == 'connected' → EMAIL\n- If prior_message_count > 0 → FOLLOW_UP\n\nSelect the best route and provide reasoning.\n\nOutput format:\nROUTE: [route name]\nREASONING: [brief explanation]",
    "variables": {
      "connection_status": "From mission.connection_status",
      "prior_message_count": "From mission.prior_message_count",
      "archetype": "From profile_analysis.archetype"
    }
  },

  "scaffold_generation_prompt": {
    "_comment": "NEW v13.0: Externalized scaffold creation logic",
    "template": "Create a message scaffold (structural outline) for the following:\n\nROUTE: {route}\nARCHETYPE: {archetype}\nWORD COUNT TARGET: {word_count_target}\nCHAR LIMIT: {char_limit}\n\nSCAFFOLD SECTIONS (based on route):\n{section_definitions}\n\nFor each section, define:\n1. SECTION_NAME: [name]\n2. WORD_RANGE: [min, max]\n3. REQUIRED: [true/false]\n4. CONSTRAINTS: [specific rules for this section]\n5. LOCKED: [false initially, can be locked during generation]\n\nOutput as JSON with 'sections' array.",
    "variables": {
      "route": "From routing decision",
      "archetype": "From profile analysis",
      "word_count_target": "From CONFIG_REGISTRY",
      "char_limit": "From CONFIG_REGISTRY",
      "section_definitions": "Route-specific section requirements from CONFIG_REGISTRY"
    }
  },

  "synthesis_prompt": {
    "_comment": "v12.0 N-candidate synthesis for C_LEVEL archetype",
    "template": "You are synthesizing multiple message drafts into a single, optimal message.\n\nCANDIDATES:\n{candidates}\n\nSYNTHESIS REQUIREMENTS:\n- Take the best elements from each candidate\n- Maintain word count target: {word_count_target} ± 30 words\n- Preserve strategic alignment between sender capabilities and recipient priorities\n- Keep the most specific, high-signal claims\n- Eliminate any generic or weak language\n- Ensure natural flow and coherence\n\nOutput ONLY the synthesized message, no preamble.",
    "variables": {
      "candidates": "Formatted list of N generated candidates with their scores",
      "word_count_target": "From scaffold constraints"
    }
  },

  "fallback_templates": {
    "_comment": "Simple fallback templates if LLM generation fails",
    "CONNECTION_REQ": "Hi {recipient_name}, I'm reaching out to {primary_verb} regarding opportunities at {company}. Looking forward to connecting.",
    "INMAIL": "Dear {recipient_name},\n\nI'm writing to {primary_verb} the exciting opportunity at {company}. With my background in AI and machine learning, I believe I can contribute significantly to your team's goals.\n\nI'd appreciate the opportunity to {secondary_verb} and learn more.\n\nBest regards",
    "EMAIL": "Dear {recipient_name},\n\nReaching out regarding {company} and the opportunity to {primary_verb} on strategic initiatives.\n\nBest regards",
    "FOLLOW_UP": "Dear {recipient_name},\n\nFollowing up on my previous message about {company}. Would you have time for a brief conversation this week?\n\nBest regards"
  },

  "qa_report_prompt": {
    "_comment": "NEW v13.0: HOP-8 QA Report generation prompt",
    "template": "Generate a comprehensive QA Report for the following workflow execution:\n\nMISSION ID: {mission_id}\n\nWORKFLOW STATE FILES:\n{state_files_summary}\n\nVALIDATION RESULTS:\n{validation_summary}\n\nLOOP EXECUTION:\n- Factual Loops (S6->S2): {factual_loop_count}\n- Creative Retries (S5): {creative_retry_count}\n\nFINAL MESSAGE:\n{final_message}\n\nGenerate a markdown report with sections:\n1. EXECUTIVE SUMMARY\n2. ARCHETYPE & ROUTE SELECTION\n3. RESEARCH QUALITY ASSESSMENT\n4. GENERATION STRATEGY\n5. VALIDATION RESULTS\n6. LOOP EXECUTION DETAILS\n7. FINAL MESSAGE QUALITY SCORE\n8. RECOMMENDATIONS\n\nBe thorough and include specific metrics from the state files.",
    "variables": {
      "mission_id": "From workflow state",
      "state_files_summary": "Summary of all HOP outputs",
      "validation_summary": "Aggregated validation results",
      "factual_loop_count": "Number of S6->S2 loops executed",
      "creative_retry_count": "Number of S5 temperature escalations",
      "final_message": "The final generated and validated message"
    }
  }
}
